\paragraph{Notation.}
Throughout the paper, $\xset$ denotes a closed convex set (our lower bounds use $\xset=\R$) and $\| \cdot \|$ denotes the Euclidean norm of a vector, and the infimum Euclidean norm in a set of vectors (or infinity if the set is empty).
%
For convex function $h:\xset \to \R$ we write (with minor abuse of notation) $\grad h(x)$ for an arbitrary subgradient of $h$ at $x$, and let $\del h(x)$ denote the set of all subgradients at $x$. 
We say that $h$ is $L$-Lipschitz if $\abs{ h(x) - h(y) } \le L \| x - y \|$ for all $u, v \in \xset$ or, equivalently, $\| \grad h(x) \| \le L$ for almost-all $x\in\xset$. We use $[n]\defeq\{1,\ldots,n\}$ and $\indic{\cdot}$ for the indicator function.
%
Throughout, $\log(\cdot)$ denotes the natural logarithm and $\N$ starts from 1.


The developments in this section use the standard notation
\[
    I(X;Y) = H(X)-H(X\mid Y)=H(Y)-H(Y\mid X)
\]
for mutual information $I(X;Y)$, entropy $H(X)=\E_{x\sim X}\log \frac{1}{\Pr(X=x)}$ and conditional entropy $H(X\mid Y) = \E_{x,y\sim X,Y}\log \frac{1}{\Pr(X=x | Y=y)}$.  We also write
\[
    h_2(q) \defeq H(\bernoulli(q)) = q \log\frac{1}{q} + (1-q) \log\frac{1}{1-q}    
\]
for the binary entropy function.


\paragraph{Stochastic optimization (SO) problems.}
A SO problem instance is a tuple $(f,P)$ containing a distribution $P$ over sample space $\sset$ and a sample objective $f:\xset\times \sset \to \R$. We write
\[
F_{f,P}(x) \defeq \E_{S\sim P} f(x;S) 
~~\mbox{and}~~
X^\star_{f,P} \defeq \argmin_{x\in\xset} F_{f,P}(x)
\]
for the population objective (which we wish to minimize) and its set of minimizers, respectively. Let $\Iclass$ denote a class of SO problem instances. We consider two fundamental classes of convex functions with a minimizer at most $R$ away from the origin.\footnote{This implicitly, and without loss of generality, assumes that optimization methods are initialized at $x_0=0$.} The first class contains problems with bounded stochastic gradient norm (i.e., where each sample function is $L$-Lipschitz),
\begin{equation*}
	\Iclass[\Lip]^{L,R} \defeq \crl*{(f,P) \mid f(\cdot; s) \text{ is convex and $L$-Lipschitz for all $s \in \sset$, and } \norm*{X^\star_{f,P}} \le R }.
\end{equation*}
The second class contains problems with bounded stochastic gradient second moment, 
%
%
\begin{equation*}
	\Iclass[\SMLip]^{L,R} \defeq 
	\crl*{(f,P) \mid f(\cdot; s) \text{ is convex $\forall s\in\sset$ and }
	\E_{S\sim P}\norm{\grad f(\cdot; S)}^2 \le L^2,\text{ and } \norm*{X^\star_{f,P}} \le R }.
	%
\end{equation*}
Clearly, $\Iclass[\Lip]^{L,R} \subset \Iclass[\SMLip]^{L,R}$, with $\Iclass[\SMLip]^{L,R}$ also including problems with heavy-tailed gradient noise.\yair{consider defining $\Iclass[*\text{-}Lip]$ and $\Mclass[*\text{-}Lip]$ as a catch-both term.}


\paragraph*{Optimization algorithms.}
General SO algorithms have unrestricted access to the function $f(\cdot;\cdot)$ but observe $P$ only through samples $S_1,S_2,\ldots\simiid P$. The output of general SO algorithms is therefore of the form
\[
%
x_{t} = \alg_t\prn[\big]{ f(\cdot; S_1) , \dots,  f(\cdot; S_T) ; \xi } \in \xset,
%
\]
where $\alg_t$ is some measurable mapping and $\xi \sim \uniform([0,1])\perp S_1, \ldots, S_T$ allows randomization.

Stochastic first-order (SFO) optimization algorithms are SO algorithms that depend on $f$ only through gradients observed at past iterates. That is, their output sequence takes the form 
\[
%
x_{t} = \alg_{t}\prn*{\grad f(x_0; S_1) , \dots,  \grad f(x_{t-1}; S_t); \xi} \in \xset,
%
\]
with $\xi \sim \uniform([0,1])\perp S_1, \ldots, S_T$ as before.
%
We write $\Aall$ and $\AFO$ for the sets of all SO and all SFO algorithms, respectively, so that $\AFO\subset \Aall$. All the algorithms from \Cref{tab:poa-upper-lower-bounds} are in $\AFO$. 


\paragraph{Error metrics.}
For an algorithm $\alg$, SO instance $(f,P)$, and budget $T$, we let $x_T$ denote the algorithm's output given $T$ samples and define the expected error to be
\begin{equation*}
	\ErrE{\alg}{(f,P)} \defeq \E F_{f,P}(x_T) - \inf_{\xopt\in\xset} F_{f,P}(\xopt),
\end{equation*}
where the expectation is with respect to $x_T$ and hence $S_1,\ldots,S_T$ and $\xi$. 
%
We similarly define the high-probability error at confidence level $\delta$ as
\begin{equation*}
	\ErrHP{\alg}{(f,P)} \defeq Q_{1-\delta}( F_{f,P}(x_T) ) - \inf_{\xopt\in\xset} F_{f,P}(\xopt),
\end{equation*}
where $Q_p(Y)=\min\{ y : \Pr( Y \le y ) \ge p\}$ denotes the $p$'th quantile of random variable $Y$ \cite[Ch. 3]{borovkov1999probability}.


Throughout, we drop the superscripts $\E$  and $\delta$ when making statements that apply to both.

\paragraph{Minimax error.}
Given an instance class $\Iclass$ and an algorithm $\alg$, we overload the notation above to denote worst-case error over the class,
\begin{equation*}
	\Err{\alg}{\Iclass} \defeq \sup_{(f,P)\in\Iclass} \Err{\alg}{(f,P)}.
\end{equation*}
%
Given an algorithm class $\Aclass$, we further overload our notation to express minimax optimal worst-case error
\begin{equation}
	\Err{\Aclass}{\Iclass} \defeq \inf_{\alg\in\Aclass} \Err{\alg}{\Iclass}
	= \inf_{\alg\in\Aclass} \sup_{(f,P)\in\Iclass} \Err{\alg}{(f,P)}.
	\label{eq:minimax-err-def}
\end{equation}


Given stochastic optimization instance ($f,P$), step size parameter $\eta$, clipping parameter $\gclip$ and initial point $x_0 \in \xset$, clipped SGD consists of the following recursion:
\begin{equation*}
    x_{t+1} = \Pi_{\xset'}\prn*{x_t - \eta \gbar_t},~~\mbox{where}~~\gbar_t \defeq \frac{g_t}{\max\{1, \norm{g_t} / \gclip\}}~~\mbox{and}~~g_t \in \del f(x_t; S_{t+1}).
    \numberthis \label{eq:clipped-SGD}
\end{equation*}

Here $\Pi_{\xset'}$ is the Euclidean projection onto $\xset' = \xset \cap \{ x \mid \norm{x-x_0} \le R\}$.


We begin with the notion of a \emph{meta-class}, i.e., a class of classes, which we denote by $\Mclass$. For any $\ell,\rho \ge 1$, we define
\begin{equation*}
	\Mclass[\Lip]^{\ell, \rho} \defeq 
	\crl*{\Iclass[\Lip]^{L,R} \mid L\in[1, \ell]\text{ and }R\in[1,\rho]}
\end{equation*}

The PoA of algorithm $\alg$ competing against all SO algorithms on meta-class $\Mclass$ is
\begin{equation*}
	\PoA{\alg}{\Mclass} \defeq \sup_{\Iclass \in \Mclass} 
	\frac{\Err{\alg}{\Iclass}}{\Err{\Aall}{\Iclass}}.
\end{equation*}

We use $\PoAE{\alg}{\Mclass}$ and $\PoAHP{\alg}{\Mclass}$ to denote the price of adaptivity w.r.t.\ expected and quantile error, respectively (i.e., with $\ErrBlank$ standing for $\ErrBlank^{\E}$ and $\ErrBlank^{\delta}$, respectively). 
We may also consider the price of adaptivity in competing against algorithms in $\Aclass\subset\Aall$, which we denote 
\begin{equation}
	\PoAGen{\alg}{\Mclass}{\Aclass} \defeq \sup_{\Iclass \in \Mclass} 
	\frac{\Err{\alg}{\Iclass}}{\Err{\Aclass}{\Iclass}}.
	\label{eq:PoAGen-def}
\end{equation}

Our strategy to lower bound the PoA in this paper is to carefully construct a collection of $n$ `hard' problem instances $(f_1, P_1), \dots, (f_n, P_n)$ such that $(f_k, P_k) \in {\Iclass}_k$ with ${\Iclass}_k \in \Mclass$  and then utilize the following observation
\begin{flalign}\label{eq:PoA-lower-bounding-strategy}
\PoAGen{\alg}{\Mclass}{\Aclass} \ge \max_{k \in [n]} 
\frac{\Err{\alg}{{\Iclass}_k}}{\Err{\Aclass}{{\Iclass}_k}} \ge \max_{k \in [n]} 
\frac{\Err{\alg}{(f_k, P_k)}}{\Err{\Aclass}{{\Iclass}_k}}.
\end{flalign}

For brevity we define $g_t = \grad f(x_t; S_{t+1})$ and $\Delta_t = f(x_t; S_{t+1}) - f(x_\star; S_{t+1})$.

