\begin{lem}\label{lem:general-mi-bound}
    For any $T\in \N$ and $\eps \in [0,1]$ and any random variable $V$, let $S_1,\ldots, S_T$ be a sequence of binary random variables such that, for all $t\le T$ \yair{could also write it as a TV distance bound}
    %
    \[
        \abs*{\Pr(S_t = 0| S_1, \ldots, S_{t-1}, V) - \half} \le \frac{\eps}{2}
    \]
     with probability 1 w.r.t.\ $S_1,\ldots, S_{t-1}$ and $V$. Then, for every randomized estimator $\hat{V}$ that depends on $V$ only through $S_1, \ldots, S_T$, we have
    \[
        I(V;\hat{V}) \le \eps^2 T.\numberthis \label{eq:general-mi-bound-1}
    \]
    If in addition $\eps \le \half$ and, for some $p\in [0,\half]$, we have that
    \[
        \abs*{\Pr(S_t = 0) - \half} \ge \eps \prn*{\frac{1}{2} - p}
    \]
    for every $t\le T$, then
    \[
        I(V;\hat{V}) \le 4p \eps^2 T.\numberthis \label{eq:general-mi-bound-2}
    \]
\end{lem}

\begin{proof}
    By the data processing inequality \citep[Theorem 2.8.1]{cover1991elements} and chain rule for mutual information \cite[Theorem 2.5.2]{cover1991elements}, 
    %
	\begin{flalign*}
		I(\hat{V}; V) & \le I(S_1, \ldots, S_T; V) 
		= \sum_{t=1}^{T} \brk[\Big]{ H(S_t \mid S_1, \ldots, S_{t-1}) - H(S_t \mid S_1, \ldots, S_{t-1}, V) }. \numberthis \label{eq:log-mi-expression}
	\end{flalign*}
	Using the facts conditioning decreases entropy and that binary random variables have entropy at most $\log 2$, we get
    \[
		H(S_t \mid S_1, \ldots, S_{t-1}) \le H(S_t) \le \log 2.
	\]
    Next, we have 
    \[
		H(S_t \mid S_1, \ldots, S_{t-1}, V) = \E_{S_1, \ldots, S_{t-1}, V} \brk*{h_2 \prn[\Big]{\Pr(S_t = 0| S_1, \ldots, S_{t-1}, V) }}
         \ge  h_2\prn*{\frac{1-\eps}{2}},
    \]
    by the assumption that $\abs*{\Pr(S_t = 0| S_1, \ldots, S_{t-1}, V) - \half} \le \frac{\eps}{2}$ with probability 1 and the fact that $h_2(x)$ has a single maximum at $x=\half$.

    Combining the last two displays and using $\log(1+x)\le x$, we obtain
    \begin{flalign*}
        H(S_t \mid S_1, \ldots, S_{t-1}) &- H(S_t \mid S_1, \ldots, S_{t-1}, V) \\& 
        \le \log 2 - h_2\prn*{\frac{1-\eps}{2}}
        \\ &=
		\frac{1+\veps}{2} \log(1+\veps) + \frac{1-\veps}{2} \log(1-\veps) 
        \le 
		\veps^2,
    \end{flalign*}
    where the last inequality is due to $\log(1+x)\le x$.
    Substituting back into~\cref{eq:log-mi-expression} yields the first claimed bound, $I(\hat{V}; V) \le \eps^2 T$. 

    To obtain the second claimed bound we use the assumption that $\abs*{\Pr(S_t = 0) - \half} \ge \eps \prn*{\frac{1}{2} - p}$ to write
    \[
		H(S_t \mid S_1, \ldots, S_{t-1}) \le H(S_t) 
        \le h_2\prn*{\frac{1-(1-2p)\eps}{2}},
    \]
    improving the bound on $H(S_t \mid S_1, \ldots, S_{t-1}) - H(S_t \mid S_1, \ldots, S_{t-1}, V)$ to 
    \begin{flalign*}
        h_2\prn*{\frac{1-(1-2p)\eps}{2}} - h_2\prn*{\frac{1-\eps}{2}}
         & \overle{(i)} 
        \prn*{\frac{1-(1-2p)\eps}{2} - \frac{1-\eps}{2}} h_2'\prn*{\frac{1-\eps}{2}}
        \\ & \overeq{(ii)} 
        p \eps \log\prn*{1+\frac{2\eps}{1-\eps}} \overle{(iii)} \frac{2p\eps^2}{1-\eps} \overle{(iv)} 4p\eps^2,
    \end{flalign*}
    due to $(i)$ concavity of binary entropy, $(ii)$ the fact that $h_2'(x) = \log\prn*{\frac{1-x}{x}}$, $(iii)$ the inequality $\log(1+x)\le x$ and $(iv)$ our assumption that $\veps \le \half$. Substituting back into~\eqref{eq:log-mi-expression}, we get that $I(\hat{V}; V) \le 4p\eps^2 T$, as required.
\end{proof}

\begin{restatable}{prop}{restatePropStandardErrorBounds}\label{prop:standard-error-bounds}
For all $R, L > 0$, instance class $\Iclass \in \{ \Iclass[\Lip]^{L,R}, \Iclass[\SMLip]^{L,R} \}$ and 
$\Aclass \in \{ \Aall, \AFO \}$, we have 
$\ErrE{\Aclass}{\Iclass}=\Theta\left( \frac{LR}{\sqrt{T} } \right)$. Moreover, for any $\delta\in(0,\half)$ we have $\ErrHP{\Aclass}{\Iclass}=\Theta\left( \frac{LR}{\sqrt{1+ {T}/{\log \frac{1}{\delta}}}} \right)$.
\end{restatable}

\begin{proof}
Since $\Iclass[\Lip]^{L,R}\subset \Iclass[\SMLip]^{L,R}$ and $\AFO\subset\Aall$, we only need to prove minimax error lower bounds on $(\Aall,\Iclass[\Lip]^{L,R})$ and minimax upper bounds on $(\AFO, \Iclass[\SMLip]^{L,R})$. 

For expected error these results are well-known. The upper bound on $\ErrE{\AFO}{ \Iclass[\SMLip]^{L,R}}$ follows, for example, by setting $\eta = \frac{R}{L\sqrt{T}}$ in \cref{eq:sgd-expected-err}. For the lower bound on $\ErrE{\Aall}{ \Iclass[\Lip]^{L,R}}$, originally due to~\citet{nemirovski1983problem}, see, e.g., \citet[Theorem 5.2.10.]{duchi2018introductory}.

For error quantiles, however, we could not find direct proof of the required upper and lower bounds, and we prove them in \Cref{app:high-prob-ms-lip,app:high-prop-lip-lb} below.
\end{proof}

\begin{customprop}{1a}\label{prop:ms-lip-hp-bound}
    For any $\delta \in (0,\half)$, any $L,R>0$, and any instance in $\Iclass[\SMLip]^{L, R}$, we have that $T$ steps of clipped SGD~\eqref{eq:clipped-SGD} with step size $\eta = \frac{R}{L\sqrt{T}}$ and $\gclip = \frac{L\sqrt{T}}{\sqrt{\log (1/\delta)}}$ produce iterates $x_0, \ldots, x_{T-1}$ whose average $\bar{x}_T = \frac{1}{T} \sum_{t=0}^{T-1} x_t$ has suboptimality $O\prn*{\frac{LR}{\sqrt{T}}\sqrt{\log\frac{1}{\delta}}}$ with probability at least $1-\delta$.
\end{customprop}

\begin{proof}
    Let $F(x) = \E_{S\sim P} f(x;S)$ be the objective function and let $\xopt$ be its minimizer in $\xset'$ (and hence, by assumption, also in $\xset$). The standard SGD regret bound, e.g., \cite[Lemma 2.12.]{orabona2021modern}, gives
    \[
    \sum_{t=0}^{T-1} \inner{\gbar_t}{x_t - \xopt} \le \frac{R^2}{2\eta} + \frac{\eta}{2} \sum_{t=0}^{T-1} \norm{\gbar_t}^2
    \]
    with probability 1. 
    Writing $\E_t Z = \Ex*{Z | x_0, \ldots, x_t}$ to streamline notation, 
    and using $\gbar_t = \E_t g_t - (\E_t g_t - \E_t \gbar_t) - (\E_t \gbar_t - \gbar_t)$ we rearrange the above display to read,
    \[
        \sum_{t=0}^{T-1} \inner{\E_t g_t}{x_t - \xopt} 
        \le \frac{R^2}{2\eta} 
        + \sum_{t=0}^{T-1} \inner{\E_t g_t - \E_t \gbar_t}{x_t - \xopt} 
        + \sum_{t=0}^{T-1} \inner{\E_t \gbar_t - \gbar_t}{x_t - \xopt}
        + \frac{\eta}{2} \sum_{t=0}^{T-1} \norm{\gbar_t}^2. 
        \numberthis \label{eq:clipped-sgd-regret-rearranged}
    \]

    Since $\E_t g_t\in\del F(x_t)$, we have $\inner{\E_t g_t}{x_t - \xopt} \ge F(x_t) - F(\xopt)$ and therefore, by Jensen's inequality we obtain the following lower bound on the LHS of \Cref{eq:clipped-sgd-regret-rearranged}
    \[
        \sum_{t=0}^{T-1} \inner{\E_t g_t}{x_t - \xopt}  \ge T \brk*{F(\bar{x}_T) - F(\xopt)}.
        \numberthis \label{eq:clipped-sgd-bound-1}
    \]
    We have $R^2 / (2 \eta) = O(LR\sqrt{T})$ by our choice of $\eta$, and it remains to bound the three sums in the RHS of \Cref{eq:clipped-sgd-regret-rearranged}.

    To bound the first sum, we observe that
    \begin{flalign*}
        \norm{\E_t g_t - \E_t \gbar_t} &\overle{(i)} \E_t \norm{g_t - \gbar_t} \overeq{(ii)} \E_t \brk*{\norm*{g_t} \prn*{1 - \frac{\gclip}{\| g_t \|} } \indic{\norm{g_t} > \gclip}} 
       \le 
        \E_t \brk*{\norm{g_t}\indic{\norm{g_t} > \gclip}}  \\ &
        \le \frac{1}{\gclip} \E_t \norm{g_t}^2 \overle{(iii)} \frac{L^2}{\gclip},
    \end{flalign*}
    where $(i)$ is from Jensen's inequality applied to the Euclidean norm, $(ii)$ from the definition of $\gbar_t$ and $(iii)$ is from the definition of $\Iclass[\SMLip]^{L, R}$. 
    Therefore, using the triangle inequality, Cauchy-Schwarz, the bound $\norm{x_t-\xopt}\le 2R$, and our setting of $\gclip$, we get that
    \[
    \abs*{\sum_{t=0}^{T-1} \inner{\E_t \gbar_t - \E_t g_t}{x_t - \xopt} } \le \sum_{t=0}^{T-1} \norm{\E_t g_t - \E_t \gbar_t} \norm{x_t - \xopt}  \le \frac{2L^2R T}{\gclip} = 2LR \sqrt{T\log\frac{1}{\delta}}.
    \numberthis \label{eq:clipped-sgd-bound-2}
    \]

    To bound the second sum, we note that $\E_t \brk*{\inner{\gbar_t - \E_t \gbar_t}{x_t - \xopt}} = 0$ for all $t$. Moreover, again by Cauchy-Schwarz and $\norm{x_t-\xopt}\le 2R$, we have that 
    \[
        \E_t \brk*{\inner{\gbar_t - \E_t \gbar_t}{x_t - \xopt}}^2
        \le 4R^2 \E_t \norm{\gbar_t - \E_t \gbar_t}^2 
        \le 4R^2 \E_t \norm{\gbar_t}^2 
        \le 4R^2 \E_t \norm{g_t}^2 
        \le 4L^2 R^2,
    \]
    as well as
    \[
        \abs*{\inner{\gbar_t - \E_t \gbar_t}{x_t - \xopt}}
        \le 
        \norm{\gbar_t - \E_t \gbar_t} \norm{x_t - \xopt}
        \le 4\gclip R,
    \]
    due to the gradient clipping.
    Therefore, we may apply \Cref{fact:freedman} on $X_t = \inner{\E_t\gbar_t -  \gbar_t}{x_t - \xopt}$ to conclude that, with probability at least $1-\frac{\delta}{2}$,
    \[
        \sum_{t=0}^{T-1} \inner{\E_t \gbar_t - \gbar_t}{x_t - \xopt}
        \le LR \sqrt{8T \log\frac{2}{\delta}} + \frac{4}{3} \gclip R \log\frac{2}{\delta} = O\prn*{LR \sqrt{T \log\frac{1}{\delta}} }.
        \numberthis \label{eq:clipped-sgd-bound-3}
    \]

    For the third and final sum, we observe that $\E_t \norm{\gbar_t}^4 \le \gclip^2 \E_t \norm{\gbar_t}^2 \le (\gclip L)^2$, and that $\norm{\gbar_t}^2 \le \gclip^2$ with probability 1. We then apply \Cref{fact:freedman} again, this time with $X_t = \norm{\gbar_t}^2$ to obtain that, with probability at least $1-\frac{\delta}{2}$,
    \begin{flalign*}
        \frac{\eta}{2} \sum_{t=0}^{T-1} \norm{\gbar_t}^2 
        & \le \frac{\eta}{2} \sum_{t=0}^{T-1} \E_t\norm{\gbar_t}^2 
        + \frac{\eta}{2} \gclip L \sqrt{ 2T \log \frac{1}{\delta}} 
        + \frac{\eta}{6} \gclip^2 \log \frac{1}{\delta}
        \\ &
        \overle{(i)} \frac{\eta}{2} L^2 T \cdot \prn*{1 + \sqrt{2} + \frac{1}{3} } \overle{(ii)} O\prn*{LR \sqrt{T }},
        \numberthis \label{eq:clipped-sgd-bound-4}
    \end{flalign*}
    due to $(i)$ the choice $\gclip$ and $\E_t\norm{\gbar_t}^2 \le \E_t\norm{g_t}^2 \le L^2$, and $(ii)$ the choice of $\eta$. 

    Substituting \cref{eq:clipped-sgd-bound-1,eq:clipped-sgd-bound-2,eq:clipped-sgd-bound-3,eq:clipped-sgd-bound-4} into \cref{eq:clipped-sgd-regret-rearranged} and using again the choice of $\eta$ and a union bound over the two events holding with probability at least $1-\frac{\delta}{2}$, we conclude that $T \brk*{F(\bar{x}_T) - F(\xopt)} \le O\prn*{LR \sqrt{T \log\frac{1}{\delta}} }$ with probability at least $1-\delta$, leading to the claimed rate of convergence.
\end{proof}

\begin{customprop}{1b}\label{prop:high-prop-lip-lb}
    For all $L,R>0$ and $\delta\in (0,\frac{1}{2})$ we have $\ErrHP{\Aall}{\Iclass[\Lip]^{L,R}} \ge 
    \Omega\prn*{  
        LR \min\crl*{ \sqrt{\frac{\log\frac{1}{\delta}}{T}}, 1 }
        }$.
\end{customprop}

\begin{proof}
    We prove \Cref{prop:high-prop-lip-lb} with a construction almost identical to the one in the proof of \Cref{thm:log-PoA-lb}. 
    We let $\xset=\R$, $\sset = \{0,1\}$ and $f:\xset\times\sset\to\R$ be
	\begin{equation*}
		f(x;s) = \begin{cases}
			L|x| & s = 0 \\
			L|x-R| & s = 1,\\
		\end{cases}
	\end{equation*}
	and we set, assuming for now $\delta \le \frac{1}{5}$,
	\begin{equation*}
		\eps \defeq \min\crl*{\sqrt{\frac{\log\frac{1-2\delta}{2\delta}}{8T}}, \frac{1}{2}}~~\mbox{and}~~\Pv \defeq \bernoulli\prn*{\frac{1+(2v-1)\eps}{2}}.
	\end{equation*}
	Clearly, $f(\cdot;s)$ is $L$-Lipschitz for both $s\in\{0,1\}$ and moreover,
    \begin{flalign*}
        F_{f,\Pv}(x) - \inf_{\xopt\in\R} F_{f,\Pv}(\xopt) \ge 
        \begin{cases}
        \eps L |x+R| & v = 0 \\
        \eps L |x-R| & v = 1.\\
        \end{cases} \numberthis \label{eq:minimax-lb-error-expression}
    \end{flalign*} 
    Consequently,  $(f, \Pv) \in \Iclass[\Lip]^{L,R}$ for $v\in \{0,1\}$.

    For any $\alg\in\Aall$, let $x_T^v$ be the output of $\alg$ when interacting with $(f,\Pv)$ by observing $S_1,\ldots,S_T\simiid \Pv$, and let $\hat{v}(x) \defeq \indic{x>0}$. Substituting into~\eqref{eq:minimax-lb-error-expression}, we have 
    \[
    \ErrHP{\alg}{(f,\Pv)} \ge \eps LR \indicb{ \Pr(\hat{v}\prn*{x_T^v} \ne v) \ge \delta }
    ~~
    \mbox{for}
    ~~
    v\in \{0,1\}.
    \]
    Therefore, since $ \max_{v\in\{0,1\}}\Pr(\hat{v}\prn*{x_T^v} \ne v) \ge \E_{V\sim \bernoulli(2\delta)}\Pr(\hat{v}\prn*{x_T^V} \ne V)$ we have
    \[
    \ErrHP{\alg}{\Iclass[\Lip]^{L,R}} \ge \eps LR \indicb{ \max_{v\in\{0,1\}}\Pr(\hat{v}\prn*{x_T^v} \ne v) \ge \delta } 
    \ge 
    \eps LR \indicb{ \E_{V\sim \bernoulli(2\delta)}\Pr(\hat{v}\prn*{x_T^V} \ne V) \ge \delta }.
    \]
    Let $\hat{V} \defeq \hat{v}\prn*{x_T^V}$ and note that it depends on $V$ only through $x_T^V$ and hence through $S_1,\ldots,S_T\simiid P_V$. By our choice of $\eps$ and the current assumption that $2 \delta < 2/5 \le 1/2$, we may apply \Cref{lem:skewed-binary-bound} with $p=2\delta$ and conclude that $\Pr(\hat{V} \ne V) \ge \delta$, implying
    \[
        \ErrHP{\alg}{\Iclass[\Lip]^{L,R}} \ge \eps LR = \Omega\prn*{  
            LR \min\crl*{ \sqrt{\frac{\log\frac{1}{\delta}}{T}}, 1 }
            }
    \]
    for all $\delta \le \frac{1}{5}$. 

    To extend the lower bound to $\delta \in (\frac{1}{5}, \frac{1}{2})$,
    %
    we only need to show that $\ErrCustom{1/2}{\alg}{\Iclass[\Lip]^{L,R}} = \Omega(LR/\sqrt{T})$. We do this with a simple ``anti-boosting'' argument. Let $k=4$ and consider $k$ copies of the construction above for $\delta'=\frac{1}{5}$, each operating on independent samples and independent coordinates, scaled so that the sum of the copies is in $\Iclass[\Lip]^{L,R}$. Concretely, the construction uses $\xset=\R^k$ and $\sset=\{0,1\}^k$, and given $f:\R\times \{0,1\}\to \R$ described above, defines $\tilde{f}: \xset\times\sset\to\R$ such that
    \[
        \tilde{f}(x,s) = k^{-3/2}\sum_{i \in [k]} f(x_i \sqrt{k};s_i).
    \]
    For $v=(v_1,\ldots,v_k)\in\{0,1\}^k$ and $P=P_{v_1}\times \cdots \times P_{v_k}$, this construction has optimality gap
    \[
        F_{f,\Pv}(x) - \inf_{\xopt\in\xset} F_{f,\Pv}(\xopt)
        \ge \tfrac{1}{k^{3/2}}\eps LR \cdot  \norm*{x \sqrt{k} - (2v-1)R}_1.
    \]
    Therefore, disagreeing with the sign of $\xopt$ in even a single coordinate implies optimality gap of at least $k^{-3/2}\eps LR = \Omega(LR/\sqrt{T})$ by our choice of $\eps$. By the discussion above, the probability of mistaking at least one of the coordinates is at least $1-(1-\delta')^k > \half$ for $\delta' = 1/5$ and $k=4$, completing the proof.
\end{proof}

\begin{proof}
	%
	%
	%
	%
	%
	 %
	We pick two elements from $\Mclass[\Lip]^{1,\rho}$, namely $\IclassMinus = \Iclass[\Lip]^{1, 1}$ and $\IclassPlus = \Iclass[\Lip]^{1, \rho}$. We then pick two instances $(f,\Pminus)$ and $(f,\Pplus)$ such that $(f, \Pv) \in \IclassV$ for $v\in \{0,1\}$. From \cref{eq:PoA-lower-bounding-strategy}, the PoA is bounded from below by
	\begin{equation*}
		\PoAE{\alg}{\Mclass[\Lip]^{1,\rho}} 
		\ge
		\max_{v\in\{0,1\}} \frac{\ErrE{\alg}{(f,\Pv)}}{\ErrE{\Aall}{\IclassV}} \ge \half \cdot \frac{\ErrE{\alg}{(f,\Pminus)}}{\ErrE{\Aall}{\IclassMinus}}
		+  \half \cdot \frac{\ErrE{\alg}{(f,\Pplus)}}{\ErrE{\Aall}{\IclassPlus}}
		.
	\end{equation*}
	Substituting $\ErrE{\Aall}{\Iclass[\Lip]^{L, R}} = O(L R / \sqrt{T} )$ as per Lemma~\ref{prop:standard-error-bounds}, we obtain
	\begin{equation}\label{eq:poa-as-expectation}
		\PoAE{\alg}{\Mclass[\Lip]^{1,\rho}} \ge \frac{\sqrt{T}}{2} \ErrE{\alg}{(f,\Pminus)} + \frac{\sqrt{T}}{2\rho} \ErrE{\alg}{(f,\Pplus)}.
	\end{equation}
	It remains to specify $f$, $\Pminus$ and $\Pplus$, argue that $(f, \Pv) \in \IclassV$ for $v\in \{0,1\}$ holds, and lower bound $\ErrE{\alg}{(f,\Pv)}$. 
	We let $\xset=\R$, $\sset = \{0,1\}$ and $f:\xset\times\sset\to\R$ be
	\begin{equation*}
		f(x;s) = \begin{cases}
			|x| & s = 0 \\
			|x-\rho| & s = 1.\\
		\end{cases}
	\end{equation*}
	Furthermore, we let 
	\begin{equation*}
		\eps \defeq \min\crl*{\sqrt{\frac{\log\rho}{8T}}, \frac{1}{2}}~~\mbox{and}~~\Pv \defeq \bernoulli\prn*{\frac{1+(2v-1)\eps}{2}}.
	\end{equation*}
	Clearly, $f(\cdot;s)$ is 1-Lipschitz for both $s\in\{0,1\}$ and moreover,
%
%
%
%
%
%
%
%
\begin{flalign}
	F_{f,\Pv}(x) - \inf_{\xopt\in\R} F_{f,\Pv}(\xopt) \ge 
	\begin{cases}
	\eps |x| & v = 0 \\
	\eps |x-\rho| & v = 1.\\
	\end{cases} \label{eq:expectation-lb-error-expression}
	\end{flalign} 
	Consequently,  $(f, \Pv) \in \IclassV$ for $v\in \{0,1\}$ as required. 

	Let $S_1, \dots, S_T\sim P_v$, yielding the  sample functions $f(\cdot, S_1), \dots, f(\cdot, S_T)$.
	To lower bound the error, let $x_T$ be the output of the algorithm after $T$ oracle queries. Using the expression~\eqref{eq:expectation-lb-error-expression}, we have
	\begin{equation*}
		\ErrE{\alg}{(f,\Pminus)} \ge \frac{\eps\rho}{2} \cdot 
		%
		\Pminus\prn*{x_T \ge \frac{\rho}{2}}
	\quad \text{and} \quad 
		\ErrE{\alg}{(f,\Pplus)} \ge \frac{\eps\rho}{2} \cdot 
		%
		\Pplus\prn*{x_T < \frac{\rho}{2}}.
	\end{equation*}
	To translate these lower bounds into the language of hypothesis testing, let $\hat{V} \defeq \indicb{x_T \ge \frac{\rho}{2}}$
	and note that, for $v\in\{0,1\}$,
	\[
		%
		\ErrE{\alg}{(f,\Pv)} \ge \frac{\eps\rho}{2} \Pv(\hat{V} \ne v ).
		%
	\]
	Substituting into~\eqref{eq:poa-as-expectation}, we have that
	%
		$\bigPoAE{\alg}{\Mclass[\Lip]^{1,\rho}} \ge \frac{\eps\sqrt{T}}{4}\prn[\big]{
			\rho \Pminus(\hat{V} \ne 0) + \Pplus(\hat{V} \ne 1)
		}$.
	%
	Writing $p \defeq \frac{1}{1+\rho}$ and letting $V\sim \bernoulli(p)$, we may rewrite the above PoA as
	\[
	%
	\PoAE{\alg}{\Mclass[\Lip]^{1,\rho}} \ge \frac{\eps\sqrt{T}}{4p} 
		\prn[\Big]{
			(1-p) \Pminus(\hat{V} \ne 0) + p \Pplus(\hat{V} \ne 1)
		}
		= \frac{\eps\sqrt{T}}{4p} \P(\hat{V} \ne V).
	%
	\]
	Noting that $p\le \half$ since $\rho \ge 1$ and that $\rho = \frac{1-p}{p}$, we invoke \Cref{lem:skewed-binary-bound} (in \Cref{app:skewed-binary-bound}) to conclude that $\P(\hat{V} \ne V) \ge \frac{p}{2}$ and therefore (recalling our choice of $\veps$)
	$\PoAE{\alg}{\Mclass[\Lip]^{1,\rho}} \ge \frac{\eps \sqrt{T}}{8} \ge 
		\frac{1}{32}\min\crl{
		\sqrt{\log\rho}, \sqrt{T}
		}$
	as required.
\end{proof}

